head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[inputCalendar > M > setInputReadOnly]<br/>컴포넌트의 inputReadOnly 속성을 설정합니다.",
    "validation" : [
        "readOnly=true 인 경우 inputReadOnly 속성은 무시됩니다.",
        "readOnly(필수) 파라미터로 날짜 편집 영역의 읽기 전용(readonly) 상태를 true/false 로 설정합니다.",
        "readOnly(필수) 파라미터로 true 설정 시 날짜 편집 영역의 읽기 전용(readonly) 상태를 설정합니다. (편집 불가)",
        "readOnly(필수) 파라미터로 true 설정 시 날짜 편집 영역은 포커스를 받을 수 있고, 마우스/키보드 관련 이벤트도 발생합니다.",
        "readOnly(필수) 파라미터로 true 설정 시 onfocus 이벤트는 발생하지 않습니다.",
        "readOnly(필수) 파라미터로 false 설정 시 날짜 편집 영역의 읽기 전용(readonly) 상태를 해제합니다. (편집 가능)",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let eList = $c.gcm.createEList(["onfocus", "onmousedown", "onkeydown", "onchange", "onclick"])

    $c.gcm.createBasicInputCalendar(eList); 
}



scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfocus=====");    
}


scwin.target1_onmousedown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onmousedown=====");    
}


scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onkeydown=====");        
}


scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onchange=====");        
}



scwin.btn_setInputReadOnly_onclick = function (e) {
	target1.setInputReadOnly(par_inputReadOnly.getText());
};



scwin.btn_setReadOnly_onclick = function (e) {
    target1.setReadOnly(par_readOnly.getText());
};
